/**
 * Retrieves the HTTP response and the categories.
 * @type {Response}
 */
const response = pm.response;
const categories = response.json();

/**
 * Verifies that the API returns HTTP status 200.
 */
pm.test("HTTP status must be 200", () => {
    pm.response.to.have.status(200);
});

/**
 * Verifies that the Content-Type header indicates a JSON response.
 */
pm.test("Content-Type is JSON", () => {
    pm.response.to.have.header("Content-Type");
    pm.expect(response.headers.get("Content-Type"))
        .to.include("application/json");
});

/**
 * Verifies that the response is a non-empty array.
 */
pm.test("Response is a non-empty array", () => {
    pm.expect(categories).to.be.an("array").that.is.not.empty;
});

/**
 * Verifies that the API returns exactly four categories.
 */
pm.test("API returns 4 categories", () => {
    pm.expect(categories).to.have.lengthOf(4);
});

/**
 * Verifies that each category contains the expected fields and types.
 */
pm.test("Each category contains the expected fields and types", () => {
    categories.forEach((category) => {
        pm.expect(category).to.have.all.keys("id", "name", "slug");
        pm.expect(category.id).to.be.a("number");
        pm.expect(category.name).to.be.a("string").and.not.empty;
        pm.expect(category.slug).to.be.a("string").and.not.empty;
    });
});

/**
 * Verifies that category IDs and slugs are unique.
 */
pm.test("Category IDs and slugs are unique", () => {
    const ids = categories.map((category) => category.id);
    const slugs = categories.map((category) => category.slug);

    const uniqueIds = new Set(ids);
    const uniqueSlugs = new Set(slugs);

    pm.expect(uniqueIds.size).to.equal(ids.length);
    pm.expect(uniqueSlugs.size).to.equal(slugs.length);
});
